-- ----------------------------
-- Table structure for dr_apply
-- ----------------------------
DROP TABLE IF EXISTS `dr_apply`;
CREATE TABLE `dr_apply`  (
  `apply_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '申报ID',
  `event_id` bigint(20) NULL DEFAULT NULL COMMENT '事件ID',
  `event_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事件编号',
  `station_id` bigint(20) NULL DEFAULT NULL COMMENT '场站ID',
  `station_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场站名称',
  `apply_power` decimal(12, 2) NULL DEFAULT NULL COMMENT '申报容量kW',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态：0待确认 1已确认 2已拒绝',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT 9999 COMMENT '租户ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  PRIMARY KEY (`apply_id`) USING BTREE,
  INDEX `idx_dr_apply_event`(`event_id`) USING BTREE,
  INDEX `idx_dr_apply_station`(`station_id`) USING BTREE,
  INDEX `idx_dr_apply_event_status`(`event_id`, `status`) USING BTREE,
  INDEX `idx_dr_apply_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 78 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '需求响应申报' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of dr_apply
-- ----------------------------

-- ----------------------------
-- Table structure for dr_assess
-- ----------------------------
DROP TABLE IF EXISTS `dr_assess`;
CREATE TABLE `dr_assess`  (
  `assess_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '评估ID',
  `event_id` bigint(20) NULL DEFAULT NULL COMMENT '事件ID',
  `event_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事件编号',
  `station_id` bigint(20) NULL DEFAULT NULL COMMENT '场站ID',
  `station_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场站名称',
  `base_power` decimal(12, 2) NULL DEFAULT NULL COMMENT '基线功率kW',
  `actual_power` decimal(12, 2) NULL DEFAULT NULL COMMENT '实际平均功率kW',
  `response_energy` decimal(12, 2) NULL DEFAULT NULL COMMENT '响应电量kWh',
  `qualified_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否合格：0否 1是',
  `charge_piles` int(11) NULL DEFAULT NULL COMMENT '充电桩数',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT 9999 COMMENT '租户ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  `points` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '超差记录',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `qual_rate` decimal(5, 2) NULL DEFAULT 0.80 COMMENT '合格线(%)',
  PRIMARY KEY (`assess_id`) USING BTREE,
  INDEX `idx_dr_assess_event`(`event_id`) USING BTREE,
  INDEX `idx_dr_assess_station`(`station_id`) USING BTREE,
  INDEX `idx_dr_assess_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 98 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VPP效果评估' ROW_FORMAT = Dynamic;

