-- ----------------------------
-- Table structure for dr_capacity_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `dr_capacity_snapshot`;
CREATE TABLE `dr_capacity_snapshot`  (
  `snapshot_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '快照ID',
  `snapshot_hour` datetime(0) NOT NULL COMMENT '快照小时（整点，如 2026-08-19 14:00:00）',
  `tenant_id` bigint(20) NOT NULL DEFAULT 9999 COMMENT '租户ID（运营商）',
  `station_id` bigint(20) NOT NULL COMMENT '场站ID',
  `peak_power` decimal(14, 2) NULL DEFAULT NULL COMMENT '削峰可调容量kW',
  `valley_power` decimal(14, 2) NULL DEFAULT NULL COMMENT '填谷可调容量kW',
  `rated_power` decimal(14, 2) NULL DEFAULT NULL COMMENT '额定装机容量kW',
  `station_count` int(11) NULL DEFAULT 0 COMMENT '参与场站数（每行固定1，聚合求和用）',
  `pile_count` int(11) NULL DEFAULT 0 COMMENT '参与桩数',
  `online_count` int(11) NULL DEFAULT 0 COMMENT '在线设备数',
  `offline_count` int(11) NULL DEFAULT 0 COMMENT '离线设备数',
  `fault_count` int(11) NULL DEFAULT 0 COMMENT '故障设备数',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`snapshot_id`) USING BTREE,
  UNIQUE INDEX `uk_station_hour`(`station_id`, `snapshot_hour`) USING BTREE,
  INDEX `idx_tenant_hour`(`tenant_id`, `snapshot_hour`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5441 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VPP首页每小时容量快照（按场站）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of dr_capacity_snapshot
-- ----------------------------

-- ----------------------------
-- Table structure for dr_dispatch
-- ----------------------------
DROP TABLE IF EXISTS `dr_dispatch`;
CREATE TABLE `dr_dispatch`  (
  `dispatch_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '分配ID',
  `event_id` bigint(20) NULL DEFAULT NULL COMMENT '事件ID',
  `event_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事件编号',
  `station_id` bigint(20) NULL DEFAULT NULL COMMENT '场站ID',
  `station_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场站名称',
  `pile_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '桩编号',
  `adjustable_power` decimal(12, 2) NULL DEFAULT NULL COMMENT '可调容量kW',
  `baseline_power` decimal(12, 2) NULL DEFAULT NULL COMMENT '基线功率kW(7日平均功率)',
  `target_power` decimal(12, 2) NULL DEFAULT NULL COMMENT '目标功率kW',
  `reduce_power` decimal(12, 2) NULL DEFAULT NULL COMMENT '压降量kW',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态：0待确认 1已确认 2已下发',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT 9999 COMMENT '租户ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  PRIMARY KEY (`dispatch_id`) USING BTREE,
  INDEX `idx_dr_dispatch_event`(`event_id`) USING BTREE,
  INDEX `idx_dr_dispatch_pile`(`pile_no`) USING BTREE,
  INDEX `idx_dr_dispatch_event_status`(`event_id`, `status`) USING BTREE,
  INDEX `idx_dr_dispatch_station`(`station_id`) USING BTREE,
  INDEX `idx_dr_dispatch_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_dr_dispatch_pile_tenant`(`pile_no`, `tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 376 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VPP调度分配' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of dr_dispatch
-- ----------------------------

-- ----------------------------
-- Table structure for dr_event
