-- ----------------------------
-- Table structure for dr_resource
-- ----------------------------
DROP TABLE IF EXISTS `dr_resource`;
CREATE TABLE `dr_resource`  (
  `resource_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '资源ID',
  `resource_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资源编码',
  `station_id` bigint(20) NULL DEFAULT NULL COMMENT '场站ID（关联dr_station.station_id）',
  `station_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场站名称',
  `pile_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '桩编号',
  `pile_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'AC' COMMENT '类型：DC直流/AC交流',
  `resource_owner_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '资源归属：1运营商 2私有',
  `rated_power` decimal(10, 2) NULL DEFAULT NULL COMMENT '额定功率kW',
  `adjustable_rate` decimal(5, 2) NULL DEFAULT 0.80 COMMENT '可调系数',
  `adjustable_power` decimal(10, 2) NULL DEFAULT NULL COMMENT '可调功率kW(=额定×系数)',
  `avg7d_power` decimal(10, 2) NULL DEFAULT NULL COMMENT '7日平均功率kW(基线，24小时平均，=额定×削峰系数)',
  `valley_rate` decimal(5, 2) NULL DEFAULT 0.20 COMMENT '填谷可调系数',
  `valley_power` decimal(10, 2) NULL DEFAULT NULL COMMENT '填谷可调功率kW',
  `participate_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '是否参与VPP：0否 1是',
  `participate_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '参与状态：0停用 1启用',
  `device_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '设备状态：1在线 2离线 3故障',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT 9999 COMMENT '租户ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  PRIMARY KEY (`resource_id`) USING BTREE,
  INDEX `idx_dr_resource_station`(`station_id`) USING BTREE,
  INDEX `idx_dr_resource_pile`(`pile_no`) USING BTREE,
  INDEX `idx_dr_resource_participate`(`participate_flag`, `participate_status`) USING BTREE,
  INDEX `idx_dr_resource_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 163 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VPP资源台账（充电桩参与虚拟电厂）' ROW_FORMAT = Dynamic;

