-- Records of dr_resource
-- ----------------------------

-- ----------------------------
-- Table structure for dr_resource_power_daily
-- ----------------------------
DROP TABLE IF EXISTS `dr_resource_power_daily`;
CREATE TABLE `dr_resource_power_daily`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
