  INDEX `idx_rpd_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23653 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VPP资源每日功率（定时任务模拟，刷新不变）' ROW_FORMAT = Dynamic;

