  `station_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场站名称',
  `response_energy` decimal(12, 2) NULL DEFAULT NULL COMMENT '响应电量kWh',
  `unit_price` decimal(10, 4) NULL DEFAULT NULL COMMENT '结算单价 元/kWh',
  `total_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '收益总额 元',
  `platform_rate` decimal(5, 2) NULL DEFAULT 0.80 COMMENT '平台分成比例',
  `operator_rate` decimal(5, 2) NULL DEFAULT 0.10 COMMENT '运营商分成比例',
  `station_rate` decimal(5, 2) NULL DEFAULT 0.10 COMMENT '场站分成比例',
  `platform_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '平台金额',
  `operator_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '运营商金额',
  `station_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '场站金额',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态：0未结算 1已结算',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT 9999 COMMENT '租户ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  `confirm_time` datetime(0) NULL DEFAULT NULL COMMENT '确认结算时间',
  `pay_time` datetime(0) NULL DEFAULT NULL COMMENT '打款时间',
  PRIMARY KEY (`settlement_id`) USING BTREE,
  INDEX `idx_dr_settlement_event`(`event_id`) USING BTREE,
  INDEX `idx_dr_settlement_station`(`station_id`) USING BTREE,
  INDEX `idx_dr_settlement_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 73 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VPP结算分账' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of dr_settlement
-- ----------------------------

-- ----------------------------
-- Table structure for dr_station
-- ----------------------------
DROP TABLE IF EXISTS `dr_station`;
CREATE TABLE `dr_station`  (
  `station_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '场站ID',
  `station_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场站名称',
  `address` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '地址',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市',
  `longitude` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度',
  `latitude` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度',
  `capacity` decimal(10, 2) NULL DEFAULT NULL COMMENT '总容量kW',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '场站方账号（关联sys_user）',
  `contact` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场站图片',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '状态：0停用 1启用',
  `operator_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '运营商分成比例（运营商在运营商+场站里的占比，NULL=默认0.5）',
  `tenant_id` bigint(20) NULL DEFAULT 9999 COMMENT '所属运营商（租户）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`station_id`) USING BTREE,
  INDEX `idx_dr_station_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_dr_station_user`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'VPP场站管理' ROW_FORMAT = Dynamic;

