  INDEX `idx_sys_logininfor_lt`(`access_time`) USING BTREE,
  INDEX `idx_logininfo_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 564 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '系统访问记录' ROW_FORMAT = Dynamic;

