-- ----------------------------
-- Procedure structure for fill_capacity_snapshot
-- ----------------------------
DROP PROCEDURE IF EXISTS `fill_capacity_snapshot`;
delimiter ;;
CREATE PROCEDURE `fill_capacity_snapshot`(IN days INT)
BEGIN
  DECLARE v_now_hour DATETIME;
  DECLARE v_hour DATETIME;
  DECLARE v_hr INT;
  DECLARE v_peak_coeff DECIMAL(6,3);
  DECLARE v_valley_coeff DECIMAL(6,3);
  DECLARE v_jitter DECIMAL(6,4);
  DECLARE v_rated_jitter DECIMAL(6,4);
  DECLARE v_online_rate DECIMAL(8,6);
  DECLARE v_offline_rate DECIMAL(8,6);
  DECLARE v_fault_rate DECIMAL(8,6);

  SET v_now_hour = DATE_FORMAT(NOW(), '%Y-%m-%d %H:00:00');

  -- 当前在线/离线/故障占比，用于估算历史各点的设备状态数
  SELECT
    CASE WHEN COUNT(*) = 0 THEN 0 ELSE SUM(device_status = '1') / COUNT(*) END,
    CASE WHEN COUNT(*) = 0 THEN 0 ELSE SUM(device_status = '2') / COUNT(*) END,
    CASE WHEN COUNT(*) = 0 THEN 0 ELSE SUM(device_status = '3') / COUNT(*) END
  INTO v_online_rate, v_offline_rate, v_fault_rate
  FROM dr_resource
  WHERE del_flag = '0' AND participate_flag = '1' AND participate_status = '1';

  SET v_hour = DATE_SUB(v_now_hour, INTERVAL days * 24 HOUR);
  WHILE v_hour < v_now_hour DO
    SET v_hr = HOUR(v_hour);

    -- 削峰可调系数：白天充电高峰可调能力大，凌晨最低
    SET v_peak_coeff = CASE v_hr
      WHEN 0 THEN 0.58 WHEN 1 THEN 0.52 WHEN 2 THEN 0.49 WHEN 3 THEN 0.47
      WHEN 4 THEN 0.50 WHEN 5 THEN 0.57 WHEN 6 THEN 0.66 WHEN 7 THEN 0.78
      WHEN 8 THEN 0.88 WHEN 9 THEN 0.95 WHEN 10 THEN 1.00 WHEN 11 THEN 1.03
      WHEN 12 THEN 1.02 WHEN 13 THEN 0.99 WHEN 14 THEN 1.04 WHEN 15 THEN 1.05
      WHEN 16 THEN 1.01 WHEN 17 THEN 0.96 WHEN 18 THEN 0.90 WHEN 19 THEN 0.86
      WHEN 20 THEN 0.82 WHEN 21 THEN 0.76 WHEN 22 THEN 0.69 ELSE 0.63 END;

    -- 填谷可调系数：夜间低谷可调能力大，白天最低（与削峰相反）
    SET v_valley_coeff = CASE v_hr
      WHEN 0 THEN 1.06 WHEN 1 THEN 1.09 WHEN 2 THEN 1.11 WHEN 3 THEN 1.11
      WHEN 4 THEN 1.08 WHEN 5 THEN 1.01 WHEN 6 THEN 0.92 WHEN 7 THEN 0.82
      WHEN 8 THEN 0.74 WHEN 9 THEN 0.69 WHEN 10 THEN 0.66 WHEN 11 THEN 0.63
      WHEN 12 THEN 0.61 WHEN 13 THEN 0.63 WHEN 14 THEN 0.66 WHEN 15 THEN 0.67
      WHEN 16 THEN 0.70 WHEN 17 THEN 0.74 WHEN 18 THEN 0.80 WHEN 19 THEN 0.86
      WHEN 20 THEN 0.92 WHEN 21 THEN 0.96 WHEN 22 THEN 1.01 ELSE 1.04 END;

    -- 每日抖动：同一天所有小时相同，天与天不同（RAND(种子) 确定性伪随机）
    SET v_jitter = 0.97 + RAND(TO_DAYS(v_hour)) * 0.06;
    -- 额定逐小时抖动 ±3%：按"天×24+小时"做种子，每个小时都不一样
    SET v_rated_jitter = 0.97 + RAND(TO_DAYS(v_hour) * 24 + v_hr) * 0.06;

       online_count, offline_count, fault_count, create_time)
    SELECT
      v_hour,
      ROUND(COALESCE(SUM(adjustable_power), 0) * v_peak_coeff * v_jitter, 2),
      ROUND(COALESCE(SUM(valley_power), 0) * v_valley_coeff * v_jitter, 2),
      ROUND(COALESCE(SUM(rated_power), 0) * v_rated_jitter, 2),
      COUNT(DISTINCT station_name),
      COUNT(*),
      ROUND(COUNT(*) * v_online_rate),
      ROUND(COUNT(*) * v_offline_rate),
      ROUND(COUNT(*) * v_fault_rate),
      NOW()
    FROM dr_resource
    WHERE del_flag = '0' AND participate_flag = '1' AND participate_status = '1'
      AND create_time <= v_hour
    ON DUPLICATE KEY UPDATE
      peak_power = VALUES(peak_power), valley_power = VALUES(valley_power),
      rated_power = VALUES(rated_power), station_count = VALUES(station_count),
      pile_count = VALUES(pile_count), online_count = VALUES(online_count),
      offline_count = VALUES(offline_count), fault_count = VALUES(fault_count);

    SET v_hour = DATE_ADD(v_hour, INTERVAL 1 HOUR);
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for fill_capacity_snapshot_by_station
-- ----------------------------
DROP PROCEDURE IF EXISTS `fill_capacity_snapshot_by_station`;
delimiter ;;
CREATE PROCEDURE `fill_capacity_snapshot_by_station`(IN days INT)
BEGIN
  DECLARE v_now_hour DATETIME;
  DECLARE v_hour DATETIME;
  DECLARE v_hr INT;
  DECLARE v_peak_coeff DECIMAL(6,3);
  DECLARE v_valley_coeff DECIMAL(6,3);
  DECLARE v_jitter DECIMAL(6,4);
  DECLARE v_rated_jitter DECIMAL(6,4);
  DECLARE v_online_rate DECIMAL(8,6);
  DECLARE v_offline_rate DECIMAL(8,6);
  DECLARE v_fault_rate DECIMAL(8,6);

  SET v_now_hour = DATE_FORMAT(NOW(), '%Y-%m-%d %H:00:00');

  -- 当前在线/离线/故障占比（全网口径估算各场站历史点的设备状态数）
  SELECT
    CASE WHEN COUNT(*) = 0 THEN 0 ELSE SUM(device_status = '1') / COUNT(*) END,
    CASE WHEN COUNT(*) = 0 THEN 0 ELSE SUM(device_status = '2') / COUNT(*) END,
    CASE WHEN COUNT(*) = 0 THEN 0 ELSE SUM(device_status = '3') / COUNT(*) END
  INTO v_online_rate, v_offline_rate, v_fault_rate
  FROM dr_resource
  WHERE del_flag = '0' AND participate_flag = '1' AND participate_status = '1';

  SET v_hour = DATE_SUB(v_now_hour, INTERVAL days * 24 HOUR);
  WHILE v_hour < v_now_hour DO
    SET v_hr = HOUR(v_hour);

    -- 削峰可调系数：白天充电高峰可调能力大，凌晨最低
    SET v_peak_coeff = CASE v_hr
      WHEN 0 THEN 0.58 WHEN 1 THEN 0.52 WHEN 2 THEN 0.49 WHEN 3 THEN 0.47
      WHEN 4 THEN 0.50 WHEN 5 THEN 0.57 WHEN 6 THEN 0.66 WHEN 7 THEN 0.78
      WHEN 8 THEN 0.88 WHEN 9 THEN 0.95 WHEN 10 THEN 1.00 WHEN 11 THEN 1.03
      WHEN 12 THEN 1.02 WHEN 13 THEN 0.99 WHEN 14 THEN 1.04 WHEN 15 THEN 1.05
      WHEN 16 THEN 1.01 WHEN 17 THEN 0.96 WHEN 18 THEN 0.90 WHEN 19 THEN 0.86
      WHEN 20 THEN 0.82 WHEN 21 THEN 0.76 WHEN 22 THEN 0.69 ELSE 0.63 END;

    -- 填谷可调系数：夜间低谷可调能力大，白天最低（与削峰相反）
    SET v_valley_coeff = CASE v_hr
      WHEN 0 THEN 1.06 WHEN 1 THEN 1.09 WHEN 2 THEN 1.11 WHEN 3 THEN 1.11
      WHEN 4 THEN 1.08 WHEN 5 THEN 1.01 WHEN 6 THEN 0.92 WHEN 7 THEN 0.82
      WHEN 8 THEN 0.74 WHEN 9 THEN 0.69 WHEN 10 THEN 0.66 WHEN 11 THEN 0.63
      WHEN 12 THEN 0.61 WHEN 13 THEN 0.63 WHEN 14 THEN 0.66 WHEN 15 THEN 0.67
      WHEN 16 THEN 0.70 WHEN 17 THEN 0.74 WHEN 18 THEN 0.80 WHEN 19 THEN 0.86
      WHEN 20 THEN 0.92 WHEN 21 THEN 0.96 WHEN 22 THEN 1.01 ELSE 1.04 END;

    -- 每日抖动：同一天所有小时相同，天与天不同（RAND(种子) 确定性伪随机）
    SET v_jitter = 0.97 + RAND(TO_DAYS(v_hour)) * 0.06;
    -- 额定逐小时抖动 ±3%：按"天×24+小时"做种子，每个小时都不一样
    SET v_rated_jitter = 0.97 + RAND(TO_DAYS(v_hour) * 24 + v_hr) * 0.06;

       online_count, offline_count, fault_count, create_time)
    SELECT
      COALESCE(tenant_id, 9999),
      station_id,
      v_hour,
      ROUND(COALESCE(SUM(adjustable_power), 0) * v_peak_coeff * v_jitter, 2),
      ROUND(COALESCE(SUM(valley_power), 0) * v_valley_coeff * v_jitter, 2),
      ROUND(COALESCE(SUM(rated_power), 0) * v_rated_jitter, 2),
      1,
      COUNT(*),
      ROUND(COUNT(*) * v_online_rate),
      ROUND(COUNT(*) * v_offline_rate),
      ROUND(COUNT(*) * v_fault_rate),
      NOW()
    FROM dr_resource
    WHERE del_flag = '0' AND participate_flag = '1' AND participate_status = '1'
      AND create_time <= v_hour
    GROUP BY COALESCE(tenant_id, 9999), station_id
    ON DUPLICATE KEY UPDATE
      peak_power = VALUES(peak_power), valley_power = VALUES(valley_power),
      rated_power = VALUES(rated_power), station_count = VALUES(station_count),
      pile_count = VALUES(pile_count), online_count = VALUES(online_count),
      offline_count = VALUES(offline_count), fault_count = VALUES(fault_count);

    SET v_hour = DATE_ADD(v_hour, INTERVAL 1 HOUR);
  END WHILE;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
